 const label=value=>{const s=String(value??'');if(language!=='en')return s;const key=s.trim();return Object.prototype.hasOwnProperty.call(labels,key)?s.replace(key,labels[key]):s;};
 window.BH_I18N={language,locale:language==='en'?'en-GB':'tr-TR',label,category:value=>language==='en'&&value==='Tarih'?'History':label(value),pick:(tr,en)=>language==='en'?en:tr,
 template:(strings,...values)=>strings.reduce((out,s,i)=>out+(language==='en'&&Object.prototype.hasOwnProperty.call(segments,s)?segments[s]:s)+(i<values.length?String(values[i]):''),'')};
 document.addEventListener('bh-static-ready',()=>{
  if(language!=='en')return;
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){const node=walker.currentNode;if(node.parentElement?.closest('script,style,textarea,[contenteditable]'))continue;node.nodeValue=label(node.nodeValue);}
  document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>{for(const attr of ['placeholder','aria-label','title'])if(el.hasAttribute(attr))el.setAttribute(attr,label(el.getAttribute(attr)));});
 },{once:true});
